-- +goose Up

-- EL BANCO DE PLATOS: que ES cada plato, para poder fotografiarlo.
--
-- Hasta ahora la guarnicion de una foto la ponia el TIPO DE NEGOCIO, asi que en
-- una cevicheria los 74 platos salian con camote, choclo y cancha al lado — el
-- sudado, el postre y la gaseosa de litro incluidos. El camote es del CEVICHE,
-- no de la cevicheria. Esta tabla es donde vive esa diferencia.
--
-- La semilla se cosecho UNA VEZ de https://api-comida-peru.luisgagocasas.com/api
-- (25 regiones, ?limit=100), datos CC BY 4.0 — la atribucion va en el aviso
-- legal. No es una dependencia: si esa API desaparece manana, esto sigue igual.
-- 509 platos, 419 nombres unicos.
--
-- Lo que la cosecha NO da, y es lo que de verdad decide la foto: como se VE el
-- plato servido. Wikipedia dice del ceviche "raw fish marinated in lime juice";
-- eso es la receta, no la foto. Los cuatro campos en ingles (aspecto,
-- recipiente, guarnicion, jamas) se escriben y se validan uno a uno con
-- cmd/fotocheck, y por eso nacen vacios aqui.
CREATE TABLE plato_tipico (
    clave      text PRIMARY KEY,
    nombre     text NOT NULL,

    -- Que cocina es. Vacio en lo cosechado; se llena en el canon comercial, que
    -- es lo que aparece en las cartas de verdad.
    cocina     text NOT NULL DEFAULT '',

    -- entrada|fondo|sopa|postre|bebida|guarnicion|otro.
    --
    -- Es el campo que llego gratis con la cosecha y arregla lo mas visible sin
    -- escribir una sola descripcion: una bebida no lleva guarnicion de plato de
    -- fondo, y una sopa va en bol, no en plato llano.
    curso      text NOT NULL DEFAULT 'fondo',

    -- Los cuatro que deciden la foto. En INGLES a proposito, como porcion.go y
    -- formato.go: es el idioma del generador y cambiarlo habria que medirlo.
    aspecto    text NOT NULL DEFAULT '',
    recipiente text NOT NULL DEFAULT '',
    guarnicion text NOT NULL DEFAULT '',

    -- Lo que el plato NO es. No es opcional en la practica: es la clausula que
    -- ya salva al pollo a la brasa de salir rostizado de supermercado.
    jamas      text NOT NULL DEFAULT '',

    -- Lo que dispara el emparejamiento con un nombre impreso. Lo cosechado trae
    -- solo su propio slug; el canon comercial trae los cortos ("ceviche"), que
    -- son los que de verdad aciertan.
    patrones   jsonb NOT NULL DEFAULT '[]',

    -- Materia prima de la cosecha para escribir los cuatro de arriba, y para
    -- que la IA los redacte en la siguiente fase.
    ingredientes jsonb NOT NULL DEFAULT '[]',

    -- Puntero a Wikimedia Commons. NO se descarga ni se sirve: es la pista para
    -- el dia que el canon lleve foto de referencia, que es el techo de calidad.
    imagen_url text NOT NULL DEFAULT '',
    region     text NOT NULL DEFAULT '',

    -- De donde salio y si alguien la miro. Sin esto el banco se degrada en
    -- silencio segun crece, y el banco es el activo.
    origen     text    NOT NULL DEFAULT 'cosecha',  -- cosecha|canon|ia|mano
    revisado   boolean NOT NULL DEFAULT false,

    creado_at      timestamptz NOT NULL DEFAULT now(),
    actualizado_at timestamptz NOT NULL DEFAULT now()
);


-- Que plato tipico es este plato de la carta, y quien lo decidio.
--
-- Se resuelve al leer, cuando la carta entra, y se guarda: emparejar en cada
-- foto seria repetir el mismo trabajo y ademas dejaria que el resultado cambiara
-- solo al ampliar el catalogo.
ALTER TABLE plato
    ADD COLUMN plato_tipico   text NOT NULL DEFAULT '',
    ADD COLUMN tipico_origen  text NOT NULL DEFAULT '';  -- regla|ia|dueno

-- +goose Down
ALTER TABLE plato DROP COLUMN tipico_origen, DROP COLUMN plato_tipico;
DROP TABLE plato_tipico;
